import { toggleNotifications } from "./actions"
import { getNotificationsEnabled } from "./preferences"

export default async function Home() {
  const enabled = await getNotificationsEnabled()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? "on" : "off"}.</p>
      <form action={toggleNotifications}>
        <button type="submit">Turn {enabled ? "off" : "on"}</button>
      </form>
    </main>
  )
}

